css:
.notification-container {
  position: relative;
  width: 380px;
  height: 120px;
  margin: 0 auto;
}

.notification-card {
  position: absolute;
  width: 100%;
  cursor: pointer;
  transition: all 0.3s ease-out;
  backdrop-filter: blur(20px);
  border-radius: 20px;
}

.notification-card:hover {
  transform: translateY(-4px);
}

.notification-card:active {
  transform: scale(0.98);
}

.notification-top {
  z-index: 30;
  top: 0;
}

.notification-top:hover {
  transform: translateY(-4px) scale(1.01);
}

.notification-middle {
  z-index: 20;
  top: 20px;
  transform: scale(0.94);
  opacity: 0.75;
}

.notification-middle:hover {
  transform: translateY(-4px) scale(0.96);
  opacity: 0.85;
}

.notification-bottom {
  z-index: 10;
  top: 40px;
  transform: scale(0.88);
  opacity: 0.5;
}

.notification-bottom:hover {
  transform: translateY(-4px) scale(0.9);
  opacity: 0.65;
}

.notification-svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 80px;
}

.notification-path {
  transition: all 0.3s ease;
}

.notification-card:hover .notification-path {
  stroke: rgba(255, 255, 255, 0.25);
}

.notification-content {
  position: relative;
  padding: 16px 20px;
  display: flex;
  align-items: center;
  gap: 12px;
  height: 80px;
}

.notification-avatar {
  width: 40px;
  height: 40px;
  border-radius: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.15);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

.user-avatar {
  font-size: 14px;
  font-weight: 600;
  color: #ffffff;
}

.notification-body {
  flex: 1;
  min-width: 0;
}

.notification-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 4px;
}

.notification-title {
  font-size: 15px;
  font-weight: 600;
  color: #ffffff;
  line-height: 1.2;
}

.notification-time {
  font-size: 12px;
  color: rgba(255, 255, 255, 0.6);
  font-weight: 400;
}

.notification-message {
  font-size: 13px;
  color: rgba(255, 255, 255, 0.8);
  line-height: 1.3;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.notification-meta {
  display: flex;
  align-items: center;
  font-size: 11px;
  color: rgba(255, 255, 255, 0.5);
  margin-top: 2px;
}

.notification-meta svg {
  width: 10px;
  height: 10px;
  margin-right: 4px;
  fill: currentColor;
}

.status-indicators {
  position: absolute;
  bottom: 2rem;
  right: 2rem;
}

.status-text {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.4);
  margin-bottom: 6px;
  text-align: center;
}

.status-dots {
  display: flex;
  gap: 6px;
  justify-content: center;
}

.status-dot-large {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.3);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
}

.status-active {
  background: rgba(255, 255, 255, 0.7);
}

.status-inactive-1 {
  background: rgba(255, 255, 255, 0.2);
}

.status-inactive-2 {
  background: rgba(255, 255, 255, 0.1);
}
